I did some further testing. This diff here implements the callback handling and adds a separate ringbuffer for usb:

```
diff --git a/ports/rp2/mphalport.c b/ports/rp2/mphalport.c
index 3385323db..e685ec42b 100644
--- a/ports/rp2/mphalport.c
+++ b/ports/rp2/mphalport.c
@@ -44,6 +44,19 @@ ringbuf_t stdin_ringbuf = { stdin_ringbuf_array, sizeof(stdin_ringbuf_array) };
 
 #endif
 
+#if MICROPY_HW_ENABLE_USBDEV
+
+STATIC uint8_t usb_ringbuf_array[256];
+ringbuf_t usb_ringbuf = { usb_ringbuf_array, sizeof(usb_ringbuf_array) };
+
+void tud_cdc_rx_cb(uint8_t itf) {
+    for (uint32_t bytes_avail = tud_cdc_n_available(itf); bytes_avail > 0; bytes_avail --) {
+        ringbuf_put(&usb_ringbuf, tud_cdc_read_char());
+    }
+}
+
+#endif
+
 #if MICROPY_KBD_EXCEPTION
 
 int mp_interrupt_char = -1;
@@ -70,7 +83,7 @@ uintptr_t mp_hal_stdio_poll(uintptr_t poll_flags) {
     }
     #endif
     #if MICROPY_HW_ENABLE_USBDEV
-    if (tud_cdc_connected() && tud_cdc_available()) {
+    if ((poll_flags & MP_STREAM_POLL_RD) && ringbuf_peek(&usb_ringbuf) != -1) {
         ret |= MP_STREAM_POLL_RD;
     }
     #endif
@@ -87,12 +100,9 @@ int mp_hal_stdin_rx_chr(void) {
         }
         #endif
         #if MICROPY_HW_ENABLE_USBDEV
-        if (tud_cdc_connected() && tud_cdc_available()) {
-            uint8_t buf[1];
-            uint32_t count = tud_cdc_read(buf, sizeof(buf));
-            if (count) {
-                return buf[0];
-            }
+        int c = ringbuf_get(&usb_ringbuf);
+        if (c != -1) {
+            return c;
         }
         #endif
         MICROPY_EVENT_POLL_HOOK
```

this seems to solve the issue. But as I see it, it's not ideal, since the NACK handshacking would no longer work. But at least the CTRL+C is solved.
